#include "thinkercad/moduledevices.hpp"
#include <iostream>
#include <stdexcept>
#include <algorithm>
using namespace thinkercad;
void require(bool condition,const char* message){if(!condition)throw std::runtime_error(message);}
CircuitPart module(std::string id,std::string model){CircuitPart part;part.id=std::move(id);part.kind=PartKind::Module;part.model=std::move(model);return part;}
int main(){
    {ModuleDevices view;auto part=module("inspect","bme280");require(!view.peekRegisters(part.id),"inspection does not initialize devices");view.i2c(part,{0xd0},-1,0);const auto snapshot=view.peekRegisters(part.id);require(snapshot&&(*snapshot)[0xd0]==0x60,"register inspection exposes actual state");require(view.i2c(part,{},1,0)==std::vector<std::uint8_t>{0x60},"inspection does not advance the device address pointer");}
    ModuleDevices bus;bus.setEmulation(true);auto bme=module("sensor","bme280");auto read=[&](CircuitPart& part,int reg,int n,Microseconds at){bus.i2c(part,{std::uint8_t(reg)},-1,at);return bus.i2c(part,{},n,at);};
    require(read(bme,0xd0,1,0)==std::vector<std::uint8_t>{0x60},"BME280 chip ID");require(read(bme,0x88,2,0)==std::vector<std::uint8_t>({0x70,0x6b}),"BME280 calibration T1");bus.i2c(bme,{0xd0,0},-1,0);require(read(bme,0xd0,1,0)[0]==0x60,"BME280 ID is read-only");bme.parameters={{"temperature",25.08},{"pressure",1006.53},{"humidity",40}};bus.i2c(bme,{0xf2,1},-1,0);bus.i2c(bme,{0xf4,0x25},-1,0);require(read(bme,0xf3,1,1000)[0]&8,"forced measurement must be busy");auto data=read(bme,0xf7,8,10000);const int rawP=(data[0]<<12)|(data[1]<<4)|(data[2]>>4),rawT=(data[3]<<12)|(data[4]<<4)|(data[5]>>4);require(rawT>=519880&&rawT<=519900,"Bosch temperature calibration example");require(rawP>=415100&&rawP<=415200,"Bosch pressure calibration example");require(!(read(bme,0xf3,1,10000)[0]&8),"measurement finishes on virtual time");require((read(bme,0xf4,1,10000)[0]&3)==0,"forced mode returns to sleep");bus.i2c(bme,{0xe0,0xb6},-1,11000);require(read(bme,0xf3,1,11500)[0]&1,"reset NVM update status");require(!(read(bme,0xf3,1,14000)[0]&1),"reset completes");
    auto spiBme=module("spi-bme","bme280-spi");bus.select(spiBme,true);bus.spi(spiBme,0xd0,0);require(bus.spi(spiBme,0,0)==0x60,"BME280 SPI register addressing");bus.select(spiBme,false);require(bus.spi(spiBme,0,0)==0xff,"unselected SPI device is high impedance");
    auto mpu=module("imu","mpu6050");require(read(mpu,0x75,1,0)[0]==0x68,"MPU6050 WHO_AM_I");require(read(mpu,0x3f,2,0)==std::vector<std::uint8_t>({0,0}),"MPU starts asleep");bus.i2c(mpu,{0x6b,0},-1,0);require(read(mpu,0x3f,2,1000)==std::vector<std::uint8_t>({0x40,0}),"MPU acceleration 1 g");bus.i2c(mpu,{0x1c,0x10},-1,1100);mpu.parameters["gyroX"]=100;bus.i2c(mpu,{0x1b,8},-1,1100);require(read(mpu,0x3f,2,2000)==std::vector<std::uint8_t>({0x10,0}),"MPU scale register changes raw acceleration");require(read(mpu,0x43,2,2000)==std::vector<std::uint8_t>({0x19,0x96}),"MPU gyro full-scale sensitivity");require(read(mpu,0x3a,1,2000)[0]&1,"MPU data-ready flag");require(read(mpu,0x3a,1,2000)[0]==0,"status read clears interrupt latch");bus.i2c(mpu,{0x6a,0x40},-1,2100);bus.i2c(mpu,{0x23,8},-1,2100);require(read(mpu,0x72,2,3000)==std::vector<std::uint8_t>({0,6}),"FIFO selected acceleration sample");require(read(mpu,0x74,6,3000).size()==6,"FIFO read length");require(read(mpu,0x72,2,3000)==std::vector<std::uint8_t>({0,0}),"FIFO drains without extra samples");
    ModuleDefinition local;local.id="test-bank";local.label="Register bank";local.bus="i2c";local.implementation="registers";local.pins={"VCC","GND","SDA","SCL"};local.address=0x48;local.registers={{0,0x42}};local.readOnly={0};local.parameters={{"temperature","Temperature","C",25,-40,85,0x10,2,100,false,true}};ModuleRegistry::install(local);auto bank=module("local","test-bank");bank.parameters["temperature"]=-12.5;require(read(bank,0x10,2,0)==std::vector<std::uint8_t>({0xfb,0x1e}),"signed parameter register encoding");bus.i2c(bank,{0,99},-1,0);require(read(bank,0,1,0)[0]==0x42,"local read-only register");bus.i2c(bank,{5,0xa5},-1,0);require(read(bank,5,1,0)[0]==0xa5,"local writable register");ModuleRegistry::removeLocal(local.id);
    auto adc=module("adc","mcp3008");std::array<double,8> voltages{};voltages[0]=1.65;voltages[1]=3.3;bus.setAnalog(adc.id,voltages,3.3);auto sample=[&](int command){bus.select(adc,true);bus.spi(adc,1,0);int value=(bus.spi(adc,std::uint8_t(command),0)&3)<<8;value|=bus.spi(adc,0,0);bus.select(adc,false);return value;};require(sample(0x80)==512,"MCP3008 half reference");require(sample(0x90)==1023,"MCP3008 full scale");require(sample(0)==0,"MCP3008 differential negative clamp");
    auto rfid=module("rfid","mfrc522");auto writeReg=[&](int reg,int value){bus.select(rfid,true);bus.spi(rfid,std::uint8_t(reg<<1),0);bus.spi(rfid,std::uint8_t(value),0);bus.select(rfid,false);};auto readReg=[&](int reg){bus.select(rfid,true);bus.spi(rfid,std::uint8_t(0x80|(reg<<1)),0);const auto value=bus.spi(rfid,0,0);bus.select(rfid,false);return value;};require(readReg(0x37)==0x92,"RC522 version");writeReg(0x09,0x50);writeReg(0x09,0);writeReg(1,3);require(readReg(0x22)==0x57&&readReg(0x21)==0xcd,"ISO14443A CRC known vector");bus.setCard(rfid.id,{0xde,0xad,0xbe,0xef});writeReg(0x14,3);writeReg(0x0a,0x80);writeReg(0x09,0x26);writeReg(0x0d,7);writeReg(1,0x0c);writeReg(0x0d,0x87);require(readReg(0x0a)==2,"REQA returns ATQA");require(readReg(9)==4&&readReg(9)==0,"ATQA bytes");writeReg(0x0a,0x80);writeReg(9,0x93);writeReg(9,0x20);writeReg(0x0d,0);writeReg(1,0x0c);writeReg(0x0d,0x80);require(readReg(0x0a)==5,"anticollision UID block");std::vector<std::uint8_t> uid;for(int i=0;i<5;++i)uid.push_back(readReg(9));require(uid==std::vector<std::uint8_t>({0xde,0xad,0xbe,0xef,0x22}),"UID and BCC");
    require(ModuleDevices::crc8({0x50,0x05,0x4b,0x46,0x7f,0xff,0x0c,0x10})==0x1c,"Dallas 1-Wire CRC known vector");std::cout<<"Device register, virtual conversion, SPI, ADC and RFID checks passed\n";
}
